    ['Elektrik enerjisi', 'Elektrik devresinde yük akışıyla elde edilen enerjidir. Elektriksel güç = gerilim × akım; enerji = güç × zaman (kWh).'],
    ['Elektrik tasarrufu', 'A++ sınıfı ürünler, LED lamba ve gereksiz cihazları kapatmak tasarruf sağlar. Güneş ve rüzgâr gibi kaynaklar elektrik üretiminde alternatiftir.'],
  ]),
  StudySumTopic('lgs_ink.s0', 'lgs_ink', 'Bir kahraman doğuyor', [
    ['Doğum ve aile', 'Mustafa Kemal 1881\'de Selanik\'te doğdu. Babası Ali Rıza Efendi, annesi Zübeyde Hanım\'dır. Küçük yaşta babasını kaybetti.'],
    ['Eğitim hayatı', 'Şemsi Efendi Mektebi, Selanik Mülkiye Rüştiyesi, Selanik Askerî Rüştiyesi (matematik öğretmeni Mustafa Efendi ona "Kemal" adını verdi), Manastır Askerî İdadisi; ardından Harbiye (1899) ve Erkân-ı Harp Okulu (1905).'],
    ['Genç subay yılları', 'Vatan ve Hürriyet cemiyetini kurdu (Şam). Trablusgarp (1911) ve Balkan savaşlarında görev aldı. Atatürk İttihat ve Terakki ile ilişkisini kısıtlı tuttu.'],
    ['Meşrutiyet ve cemiyetler', 'II. Meşrutiyet 1908\'de ilan edildi. İttihat ve Terakki hükümette etkili oldu. Osmanlı toplumunda Osmanlıcılık, İslamcılık, Türkçülük ve Batıcılık akımları tartışıldı.'],
    ['Çanakkale Savaşları', '1915\'te Mustafa Kemal, Conkbayırı\'nda ve Arıburnu\'nda önemli roller üstlendi. Anafartalar Grup Komutanı olarak düşmanı yendi. Çanakkale geçilmedi.'],
    ['Doğu cepheleri', '1916\'da Mustafa Kemal, Muş ve Bitlis\'in kurtarılmasında rol oynadı ve general oldu. Daha sonra Suriye cephesinde Yıldırım Orduları\'nda görev yaptı.'],
    ['I. Dünya Savaşı ve sonrası', 'Osmanlı savaşa Almanya yanında katıldı. Savaş 1918\'de yenilgiyle bitti. 30 Ekim 1918 Mondros Ateşkes Antlaşması imzalandı.'],
    ['Osmanlı\'nın durumu', 'Siyasi çözülme, ekonomik bozulma ve azınlık sorunları devleti zayıflattı; işgaller başladı ve ulus devlete geçiş fikri güçlendi.'],
  ]),
  StudySumTopic('lgs_ink.s1', 'lgs_ink', 'Milli uyanış', [
    ['Mondros ve işgaller', 'Mondros Ateşkesi\'nden sonra İtilaf devletleri Anadolu\'yu işgal etti. İzmir\'in Yunanlılarca işgali (15 Mayıs 1919) halkta büyük tepki yarattı.'],
    ['Kuvâ-yi Milliye', 'Halkın kendi imkânlarıyla kurduğu direniş birlikleridir. Cemiyetler (Müdafaa-i Hukuk) bölgesel savunma örgütleri kurdu.'],
    ['Mustafa Kemal Samsun\'da', '19 Mayıs 1919\'da Samsun\'a çıktı. Bu tarih Millî Mücadele\'nin başlangıcı kabul edilir; Atatürk\'ün bu görevi, 9. Ordu Müfettişliği (dağılan orduları toplamak) kılıfıyla verilmişti.'],
    ['Havza ve Amasya Genelgesi', 'Havza Genelgesi (Mayıs 1919) mitingleri başlattı. Amasya Genelgesi (22 Haziran 1919): "Vatanın bütünlüğü, milletin istiklali tehlikededir." Milli egemenliğe dayalı ilk belge sayılır.'],
    ['Erzurum Kongresi', '23 Temmuz - 7 Ağustos 1919 yapıldı. Vatanın bütünlüğü ve milli sınırlar vurgulandı. Mustafa Kemal heyet-i temsiliye başkanı oldu.'],
    ['Sivas Kongresi', '4-11 Eylül 1919. Bölgesel cemiyetler "Anadolu ve Rumeli Müdafaa-i Hukuk Cemiyeti" altında birleşti. Manda ve himaye reddedildi.'],
    ['Amasya Görüşmeleri ve Misak-ı Millî', 'Amasya Görüşmeleri\'nde hükümet, Heyet-i Temsiliye\'yi tanıdı. Son Osmanlı Meclisi-i Mebusanı Ocak 1920\'de Misak-ı Millî\'yi (Milli Misak) kabul etti.'],
    ['TBMM\'nin açılışı', 'İstanbul\'un işgali (16 Mart 1920) üzerine Mustafa Kemal 23 Nisan 1920\'de Ankara\'da Büyük Millet Meclisi\'ni açtı. Meclis, yasama ve yürütme yetkisini birlikte kullandı.'],
  ]),
  StudySumTopic('lgs_ink.s2', 'lgs_ink', 'Milli bir destan', [
    ['Doğu ve Güney cepheleri', 'Doğu Cephesi\'nde Kâzım Karabekir komutasında Ermenilere karşı Gümrü Antlaşması (1920) imzalandı. Güney Cephesi\'nde Antep, Maraş ve Urfa halkı Fransızlara karşı direndi.'],
    ['Düzenli ordu', 'Kuvâ-yi Milliye\'den düzenli orduya geçildi. Çerkez Ethem isyanı bastırıldı.'],
    ['I. İnönü (Ocak 1921) ve II. İnönü (Mart 1921)', 'Batı Cephesi\'nde Yunan ilerleyişi durduruldu. Türk ordusunun düzenli ordu olarak ilk başarısıdır. İstiklal Marşı 12 Mart 1921\'de kabul edildi.'],
    ['Sakarya Meydan Muharebesi', '23 Ağustos - 13 Eylül 1921. "Hattı müdafaa yoktur, sathı müdafaa vardır; o satıh bütün vatandır." Mustafa Kemal\'e "Mareşal" rütbesi ve "Gazi" unvanı verildi.'],
    ['Büyük Taarruz', '26 Ağustos 1922\'de başladı. Başkomutanlık Meydan Muharebesi 30 Ağustos\'ta kazanıldı. 9 Eylül 1922\'de İzmir kurtarıldı. "Ordular, ilk hedefiniz Akdeniz\'dir, ileri!"'],
    ['Mudanya Ateşkesi', '11 Ekim 1922. Doğu Trakya, TBMM hükümetine bırakıldı. Savaşın askerî dönemi bitti.'],
    ['Saltanatın kaldırılması', '1 Kasım 1922\'de saltanat kaldırıldı; son padişah Vahdettin ülkeyi terk etti.'],
    ['Lozan Antlaşması', '24 Temmuz 1923. Türkiye\'nin bağımsızlığı uluslararası alanda tanındı. Kapitülasyonlar kalktı; sınırlar çizildi; Boğazlar sorunu (Montrö\'ye kadar) bırakıldı.'],
    ['Cumhuriyetin ilanı', '29 Ekim 1923\'te Cumhuriyet ilan edildi, Mustafa Kemal ilk Cumhurbaşkanı seçildi. Ankara başkent yapıldı (13 Ekim 1923).'],
  ]),
  StudySumTopic('lgs_ink.s3', 'lgs_ink', 'Atatürkçülük ve çağdaşlaşan Türkiye', [
    ['Atatürk ilkeleri', 'Cumhuriyetçilik, milliyetçilik, halkçılık, devletçilik, laiklik ve inkılapçılık (6 ilke). 1937\'de anayasaya girdi.'],
    ['Cumhuriyetçilik ve halkçılık', 'Cumhuriyetçilik: egemenlik halkındır. Halkçılık: sınıf ayrımı yoktur; kanun önünde eşitlik.'],
    ['Milliyetçilik ve devletçilik', 'Milliyetçilik: ortak ülkü ve milli bağlılık. Devletçilik: ekonomide özel girişim yetersiz kalınca devlet de yatırım yapar.'],
    ['Laiklik ve inkılapçılık', 'Laiklik: din ve devlet işlerinin ayrılması. İnkılapçılık: sürekli yenilenme, çağdaşlaşma.'],
    ['Siyasi inkılaplar', 'Saltanatın kaldırılması (1922), Cumhuriyet (1923), Halifeliğin kaldırılması (3 Mart 1924), Anayasa 1924.'],
    ['Hukuk ve eğitim inkılapları', 'Medeni Kanun (1926), Tevhid-i Tedrisat (1924), Medreselerin kapatılması, Harf İnkılabı (1928), TDK (1932), Millet Mektepleri.'],
    ['Toplumsal inkılaplar', 'Şapka Kanunu (1925), Tekke ve zaviyelerin kapatılması (1925), Soyadı Kanunu (1934), kadın hakları (1930 belediye seçimlerinde, 1934 milletvekili seçme/seçilme), Uluslararası saat ve takvim.'],
    ['Ekonomik inkılaplar', 'Aşar\'ın kaldırılması (1925), İzmir İktisat Kongresi (1923), İş Bankası (1924), Sanayi Teşvik Kanunu, Birinci Beş Yıllık Sanayi Planı (1934).'],
  ]),
  StudySumTopic('lgs_ink.s4', 'lgs_ink', 'Demokratikleşme çabaları', [
    ['Çok partili hayata ilk adım', 'Terakkiperver Cumhuriyet Fırkası 1924\'te kuruldu; Şeyh Said İsyanı (1925) sonrası kapatıldı.'],
    ['Şeyh Said İsyanı', 'Şubat 1925\'te çıktı. Takrir-i Sükûn Kanunu çıkarıldı, İstiklal Mahkemeleri kuruldu.'],
    ['Serbest Cumhuriyet Fırkası', '1930\'da Ali Fethi Okyar tarafından kuruldu; kısa sürede muhalefet odağı oldu ve kendini feshetti.'],
    ['Menemen Olayı', '1930\'da Menemen\'de Kubilay\'ın şehit edilmesiyle çıkan irticai olay; laikliğe yönelik tehdit olarak görüldü.'],
    ['Çok partili hayat', '1946\'da Demokrat Parti\'nin kurulmasıyla çok partili hayata kalıcı geçiş yapıldı.'],
    ['Atatürk dönemi demokrasi anlayışı', 'Milli egemenlik ve halkçılık temelli bir demokrasi hedeflendi. 1934\'te kadınlara seçme ve seçilme hakkı tanındı.'],
    ['Anayasa değişiklikleri', '1921 Teşkilat-ı Esasiye, 1924 Anayasası ve 1937 değişiklikleriyle devletin niteliği (cumhuriyetçi, milliyetçi, halkçı, devletçi, laik ve inkılapçı) belirlendi.'],
  ]),
  StudySumTopic('lgs_ink.s5', 'lgs_ink', 'Atatürk dönemi Türk dış politikası', [
    ['Barış politikası', '"Yurtta sulh, cihanda sulh" ilkesi. Yeni Türkiye komşularıyla dostluk ve uluslararası iş birliğine önem verdi.'],
    ['Musul sorunu', 'Lozan\'da çözülemedi. 1926 Ankara Antlaşması ile Musul İngiliz mandasındaki Irak\'a bırakıldı.'],
    ['Milletler Cemiyeti ve dostluk paktları', '1932\'de Milletler Cemiyeti\'ne üye olundu. Balkan Antantı (1934) ve Sadabat Paktı (1937) bölgesel güvenlik için yapıldı.'],
    ['Montrö Boğazlar Sözleşmesi', '1936. Türkiye Boğazlar üzerinde tam egemenlik kazandı.'],
    ['Hatay\'ın anavatana katılması', 'Hatay 1938\'de bağımsız devlet oldu, 1939\'da halk oylamasıyla Türkiye\'ye katıldı.'],
    ['II. Dünya Savaşı öncesi', 'Atatürk\'ün ölümünden sonra İsmet İnönü döneminde Türkiye savaşa girmedi, aktif tarafsızlık politikası izledi.'],
    ['Dış politikanın temel özellikleri', 'Barışçıl, gerçekçi, bağımsızlıkçı ve uluslararası hukuka bağlı bir politika izlendi.'],
  ]),
  StudySumTopic('lgs_ink.s6', 'lgs_ink', 'Atatürk\'ün ölümü ve sonrası', [
    ['Atatürk\'ün vefatı', '10 Kasım 1938\'de İstanbul Dolmabahçe Sarayı\'nda saat 09.05\'te vefat etti. Cenazesi önce Etnografya Müzesi\'ne, 1953\'te Anıtkabir\'e nakledildi.'],
    ['Atatürk\'ün vasiyeti', 'Malvarlığının bir kısmını Türk Dil Kurumu ve Türk Tarih Kurumu\'na, Türkiye İş Bankası ve yakınlarına bıraktı.'],
    ['Atatürk\'ün düşüncesi ve ilkeleri', 'Akıl ve bilim, millî egemenlik, çağdaşlık; "Hayatta en hakiki mürşit ilimdir."'],
    ['Atatürk sonrası dönem', 'İsmet İnönü cumhurbaşkanı oldu (1938). II. Dünya Savaşı\'nda Türkiye savaş dışı kaldı; savaşın sonunda BM\'ye üye oldu (1945).'],
    ['Atatürk\'ün dünya görüşü', 'Barışçıl, insan sevgisine ve eşitliğe dayalı bir anlayış. "Yurtta sulh, cihanda sulh."'],
    ['Atatürk\'ün gençliğe önemi', '19 Mayıs Atatürk\'ü Anma, Gençlik ve Spor Bayramı; "Ey Türk gençliği!" ile başlayan Gençliğe Hitabe.'],
    ['Dil ve tarih çalışmaları', 'Türk Tarih Kurumu (1931), Türk Dil Kurumu (1932). Türk tarihinin ve dilinin bilimsel yöntemlerle incelenmesi amaçlandı.'],
  ]),
  StudySumTopic('lgs_din.s0', 'lgs_din', 'Kader inancı', [
    ['Kader nedir', 'Allah\'ın her şeyi öncesiz ilmiyle bilmesi ve takdir etmesidir. Kaza: takdir edilenin zamanı geldiğinde yaratılmasıdır.'],
    ['İlim ve irade', 'Allah geçmişi, geleceği ve her şeyi bilir (ilim). Allah\'ın bilmesi, insanı zorlamak anlamına gelmez; insan seçimlerinden sorumludur.'],
    ['Cüz\'i irade', 'Allah\'ın insana verdiği, seçim yapabilme gücüdür. İnsan iyiliği de kötülüğü de seçebilir; sorumluluk buradan doğar. Allah\'ın bilmesi seçimi belirlemez.'],
    ['Kader ve sorumluluk', 'Kader inancı çalışmayı, tedbiri ve sorumluluğu ortadan kaldırmaz. İnsan sebeplere sarılır, sonucu Allah\'a bırakır.'],
    ['Tevekkül', 'Çalışıp gereken tedbiri aldıktan sonra sonucu Allah\'a havale etmek. Tevekkül tembellik değildir.'],
    ['Dua', 'Allah\'a yalvarmak, ondan istekte bulunmaktır. Duanın kadere etkisi: sebeplere sarılıp dua etmek, kader inancıyla çelişmez.'],
    ['Ecel ve rızık', 'Ecel: ömrün sonu; rızık: Allah\'ın verdiği nimetlerdir. Rızık için helal yoldan çalışmak gerekir. Ecel ve rızık Allah\'ın bilgisi altındadır.'],
    ['Kader inancının faydaları', 'Başarıda şımarmamayı, başarısızlıkta ümitsizliğe düşmemeyi, sabrı, şükrü ve huzuru güçlendirir.'],
  ]),
  StudySumTopic('lgs_din.s1', 'lgs_din', 'Zekât ve sadaka', [
    ['Zekât', 'Belli bir miktar mala (nisap) sahip Müslümanın, malının belli bir kısmını (genelde %2,5 yani 1/40) ihtiyaç sahiplerine vermesidir. İslam\'ın şartlarındandır.'],
    ['Zekâtın şartları', 'Akıllı, ergin ve hür Müslüman olmak; nisap miktarı mala sahip olmak; malın üzerinden bir yıl geçmek; temel ihtiyaçlardan ve borçlardan fazla olmak.'],
    ['Zekât verilecek yerler', 'Tevbe suresi 60. ayette sekiz grup sayılır: fakirler, miskinler, zekât toplayanlar, kalpleri İslam\'a ısındırılacaklar, köleler, borçlular, Allah yolunda olanlar, yolda kalmışlar.'],
    ['Zekât verilmeyecekler', 'Anne-baba, dede-nine, çocuk ve torunlara; eşe; zengin kişilere zekât verilmez.'],
    ['Sadaka', 'Allah rızası için verilen her türlü yardımdır. Zorunlu değil, gönüllüdür; para olabileceği gibi güler yüz ve yardım da sadakadır.'],
    ['Fitre (sadaka-i fıtır)', 'Ramazan bayramından önce, nisap miktarı mala sahip kişilerin verdiği vacip bir yardımdır.'],
    ['İnfak ve vakıf', 'İnfak: Allah yolunda mal harcamak. Vakıf: bir malın kalıcı olarak toplumun hayrına tahsis edilmesi; sadaka-i câriye (devam eden sadaka) örneğidir.'],
    ['Zekât ve sadakanın toplumsal faydası', 'Yoksulluğu azaltır, toplumda yardımlaşma ve dayanışmayı güçlendirir, zenginle fakir arasındaki mesafeyi azaltır, cimrilik ve hırsı terbiye eder.'],
  ]),
  StudySumTopic('lgs_din.s2', 'lgs_din', 'Din ve hayat', [
    ['Dinin amacı', 'İnsanın dünya ve ahiret mutluluğunu sağlamak; temel korunacak değerler: can, akıl, din, nesil, mal.'],
    ['Ahlak', 'İyi ve kötü davranışları ayırt etmeyi ve iyi olanı uygulamayı hedefler. Peygamberimiz: "Ben güzel ahlakı tamamlamak için gönderildim."'],
    ['Kul hakkı', 'Başkalarına ait haklara saygıdır. Kul hakkını yemek affedilmesi zor bir günahtır; hak sahibi helallik vermedikçe bitmez.'],
    ['Helal-haram', 'İslam\'ın serbest bıraktığı şeyler helal, yasakladığı şeyler harâmdır. Kazancın helal olması ve harama bulaşmamak önemlidir.'],
    ['Din kardeşliği ve hoşgörü', 'Müslümanlar kardeştir; farklı inanç ve düşüncelere saygı, İslam\'ın temel ilkesidir. "Size göre dininiz, bana göre dinim."'],
    ['Din ve akıl', 'Kur\'an akla ve düşünmeye önem verir. "Aklını kullanmıyor musunuz?" ayeti ve ilim öğrenmenin teşviki bu anlayışın örnekleridir.'],
    ['İbadet ve ahlak ilişkisi', 'Namaz kötülükten alıkoyar; oruç sabrı öğretir; zekât paylaşmayı, hac eşitliği ve birliği öğretir. İbadetlerin ahlaka yansıması gerekir.'],
    ['Din ve bilim', 'İslam, ilim öğrenmeyi farz kabul eder. Bilimsel çalışmalar insanlığın hizmetine olursa ibadet gibidir.'],
  ]),
  StudySumTopic('lgs_din.s3', 'lgs_din', 'Hz. Muhammed\'in örnekliği', [
    ['Doğumu ve çocukluğu', 'Hz. Muhammed 571\'de Mekke\'de doğdu (Fil Vakası yılı). Babası Abdullah doğumundan önce, annesi Amine altı yaşında vefat etti. Dedesi Abdülmuttalib ve amcası Ebu Talib\'in himayesinde büyüdü.'],
    ['Gençliği ve Muhammedü\'l-Emin', 'Doğruluğu, güvenilirliği ile "el-Emin" unvanını aldı. Hz. Hatice ile evlendi. Hılfü\'l-Fudûl\'e katıldı; Kâbe\'nin yenilenmesi sırasında Hacerü\'l-Esved anlaşmazlığını çözdü.'],
    ['Peygamberliği', '610\'da Hira Mağarası\'nda ilk vahiy geldi ("İkra", Alak suresi). Üç yıl gizli, sonra açıktan tebliğ etti.'],
    ['Hicret', '622\'de Mekke\'den Medine\'ye hicret etti. Medine Vesikası ile farklı gruplar arasında hukuk ve barış sağlandı. Hicret, İslam takviminin başlangıcıdır.'],
    ['Mekke\'nin fethi', '630\'da Mekke kansız fethedildi. Hz. Peygamber "Bugün size bir kınama yoktur. Gidiniz, hepiniz serbestsiniz." diyerek genel af ilan etti.'],
    ['Veda Hutbesi', '632\'de Veda Haccı\'nda okundu. İçeriği: can ve mal dokunulmazlığı, kadın hakları, faiz yasağı, eşitlik ("Arap\'ın Arap olmayana üstünlüğü yoktur; üstünlük takvadadır.").'],
    ['Hz. Muhammed\'in örnek ahlakı', 'Dürüstlük, merhamet, hoşgörü, adalet, alçakgönüllülük, sabır ve yardımseverlik. "Siz için Allah\'ın Resulünde güzel bir örnek vardır." (Ahzab 21)'],
    ['Vefatı', '632\'de Medine\'de 63 yaşında vefat etti. Kabri Mescid-i Nebevi\'dedir. Örnek yaşantısı sünnet ve hadislerle günümüze ulaşmıştır.'],
  ]),
  StudySumTopic('lgs_din.s4', 'lgs_din', 'Kur\'an-ı Kerim ve yorumu', [
    ['Kur\'an\'ın indirilişi', 'Kur\'an yaklaşık 23 yılda, Cebrail aracılığıyla Hz. Muhammed\'e vahyedildi. İlk ayetler Hira Mağarası\'nda geldi.'],
    ['Kur\'an\'ın yapısı', '114 sure, 30 cüz ve yaklaşık 6236 ayetten oluşur. Fatiha ilk, Nas son suredir. Bakara en uzun suredir.'],
    ['Kur\'an\'ın toplanması', 'Vahiy kâtipleri tarafından yazıldı. Hz. Ebubekir döneminde sayfalar bir araya getirildi; Hz. Osman döneminde çoğaltılıp Mushaf hâline getirildi.'],
    ['Kur\'an\'ın temel konuları', 'İnanç esasları, ibadetler, ahlak, kıssalar (peygamber ve geçmiş toplum hikâyeleri), adalet ve sosyal hayatla ilgili ilkeler.'],
    ['Tefsir ve meal', 'Tefsir: ayetlerin geniş açıklamasıdır. Meal: ayetlerin anlamının başka bir dile aktarılmasıdır; tefsir yerine geçmez.'],
    ['Kur\'an\'ı anlamak', 'Ayetleri indiği tarihsel ve toplumsal ortamla birlikte, bütünlük içinde değerlendirmek gerekir. Sünnet, Kur\'an\'ı anlamada rehberdir.'],
    ['Kur\'an\'ın evrensel mesajları', 'Adalet, eşitlik, barış, hoşgörü, ilmin ve aklın değeri, insan onuru, yetim ve yoksulun korunması.'],
    ['Kur\'an\'a saygı ve okuma adabı', 'Kur\'an temiz bir ortamda, abdestli olarak okunur; tertil ile (anlaşılır) okunur; anlamı üzerinde düşünülür. Güzel okumak, anlamak ve yaşamak üç aşamadır.'],
  ]),
  StudySumTopic('lgs_din.s5', 'lgs_din', 'Ahiret ve diğer inanç esasları', [
    ['İman esasları', 'Altı: Allah\'a, meleklere, kitaplara, peygamberlere, ahiret gününe ve kadere (hayır ve şerrin Allah\'tan olduğuna) iman.'],
    ['Ahiret inancı', 'Ölümden sonra dirilişe, hesaba, mizana (terazi), sırata, cennet ve cehenneme inanmaktır. Dünya hayatı ahiretin tarlasıdır.'],
    ['Melekler', 'Allah\'ın nurdan yarattığı, emirlerine itaat eden varlıklardır. Cebrail (vahiy), Mikail (rızık), İsrafil (sur), Azrail (ölüm) başlıca meleklerdir.'],
    ['İlahi kitaplar', 'Tevrat (Hz. Musa), Zebur (Hz. Davud), İncil (Hz. İsa) ve Kur\'an (Hz. Muhammed). Kur\'an son ve değiştirilmeyen ilahi kitaptır.'],
    ['Peygamberler', 'Allah\'ın insanlara gönderdiği elçilerdir. Özellikleri: sıdk (doğruluk), emanet, fetanet (akıllılık), tebliğ, ismet (günahsızlık).'],
    ['Namaz ve oruç', 'Namaz günde beş vakit kılınır (sabah, öğle, ikindi, akşam, yatsı). Oruç Ramazan ayında tutulur; sabrı ve iradeyi güçlendirir.'],
    ['Hac ve diğer şartlar', 'İslam\'ın beş şartı: kelime-i şehadet, namaz, oruç, zekât, hac (gücü yetenlere ömürde bir defa farz).'],
    ['Dua ve zikir', 'Dua, Allah\'a yöneliş ve istek bildirmedir. Zikir ise Allah\'ı anmak ve onun adlarıyla meşgul olmaktır.'],
